    shortAnswer: "逆变器把直流母线电压变成可控的三相交流电压，给电机供电。它通过6个功率开关按PWM规律高速导通和关断，合成所需三相电压。",
    answer: "电池或直流母线提供的是直流电，但三相电机需要随时间变化的三相电压和电流。三相两电平逆变器通常由3个桥臂、6个MOSFET或IGBT组成，每个桥臂控制一相。控制器通过PWM决定各开关什么时候导通和关断，从而改变三相端电压。可以把逆变器理解成FOC和电机之间真正执行电压指令的功率执行器。",
